/**
 * Drizzle schema. Keep this file free of Expo/React Native imports so the
 * Node seed scripts (scripts/seed/) can reuse it.
 *
 * Conventions:
 * - IDs are UUID strings, generated by the app (no DB default).
 * - Every user-editable table has createdAt / updatedAt / deletedAt.
 *   Never hard-delete rows: set deletedAt instead (required for future sync).
 * - Nutrient columns are nullable: null means unknown, never 0.
 */
import { sql } from 'drizzle-orm';
import {
  type AnySQLiteColumn,
  check,
  index,
  integer,
  real,
  sqliteTable,
  text,
  uniqueIndex,
} from 'drizzle-orm/sqlite-core';

import type { Nutrient } from '@/lib/nutrition';

export const SEXES = ['male', 'female'] as const;
export const ACTIVITY_LEVELS = ['sedentary', 'light', 'moderate', 'active', 'veryActive'] as const;
export const GOALS = ['lose', 'maintain', 'gain'] as const;
export const LANGUAGES = ['mk', 'en'] as const;
export const RING_MODES = ['eaten', 'left'] as const;
export const FOOD_KINDS = ['ingredient', 'dish', 'product', 'recipe'] as const;
export const FOOD_SOURCES = ['usda', 'seed', 'user'] as const;

export type Sex = (typeof SEXES)[number];
export type ActivityLevel = (typeof ACTIVITY_LEVELS)[number];
export type Goal = (typeof GOALS)[number];
export type RingMode = (typeof RING_MODES)[number];

export type TargetOverrides = Partial<Record<Nutrient, number>>;

const timestamps = {
  createdAt: integer({ mode: 'timestamp_ms' })
    .notNull()
    .$defaultFn(() => new Date()),
  updatedAt: integer({ mode: 'timestamp_ms' })
    .notNull()
    .$defaultFn(() => new Date())
    .$onUpdateFn(() => new Date()),
  deletedAt: integer({ mode: 'timestamp_ms' }),
};

// Per-100g on foods, or for the logged amount on logEntries.
const nutrients = {
  kcal: real(),
  protein: real(),
  carbs: real(),
  fat: real(),
  fiber: real(),
  sugar: real(),
  salt: real(),
};

export const profile = sqliteTable('profile', {
  id: text().primaryKey(),
  sex: text({ enum: SEXES }).notNull(),
  birthDate: text().notNull(), // 'YYYY-MM-DD'
  heightCm: real().notNull(),
  weightKg: real().notNull(),
  activityLevel: text({ enum: ACTIVITY_LEVELS }).notNull(),
  goal: text({ enum: GOALS }).notNull(),
  goalRateKgPerWeek: real().notNull().default(0),
  language: text({ enum: LANGUAGES }).notNull(),
  ringMode: text({ enum: RING_MODES }).notNull().default('eaten'),
  targetOverrides: text({ mode: 'json' }).$type<TargetOverrides>(),
  ...timestamps,
});

export const foods = sqliteTable(
  'foods',
  {
    id: text().primaryKey(),
    nameMk: text(),
    nameEn: text(),
    searchKey: text().notNull(), // toSearchKey(nameMk + ' ' + nameEn)
    kind: text({ enum: FOOD_KINDS }).notNull(),
    ...nutrients,
    source: text({ enum: FOOD_SOURCES }).notNull(),
    sourceRef: text(), // USDA fdcId
    basedOnFoodId: text().references((): AnySQLiteColumn => foods.id),
    isEstimate: integer({ mode: 'boolean' }).notNull().default(false),
    cookedWeightG: real(), // recipes only
    // Nutrients whose value is a lower bound because some recipe ingredient is unknown.
    incompleteNutrients: text({ mode: 'json' }).$type<Nutrient[]>(),
    ...timestamps,
  },
  (t) => [
    uniqueIndex('foods_source_ref_idx').on(t.source, t.sourceRef),
    check('foods_has_name', sql`${t.nameMk} is not null or ${t.nameEn} is not null`),
  ],
);

export const portions = sqliteTable(
  'portions',
  {
    id: text().primaryKey(),
    foodId: text()
      .notNull()
      .references(() => foods.id),
    nameMk: text(),
    nameEn: text(),
    grams: real().notNull(),
    ...timestamps,
  },
  (t) => [
    index('portions_food_idx').on(t.foodId),
    check('portions_has_name', sql`${t.nameMk} is not null or ${t.nameEn} is not null`),
    check('portions_grams_positive', sql`${t.grams} > 0`),
  ],
);

export const recipeIngredients = sqliteTable(
  'recipeIngredients',
  {
    id: text().primaryKey(),
    recipeFoodId: text()
      .notNull()
      .references(() => foods.id),
    ingredientFoodId: text()
      .notNull()
      .references(() => foods.id),
    grams: real().notNull(),
    sortOrder: integer().notNull().default(0),
    ...timestamps,
  },
  (t) => [
    index('recipe_ingredients_recipe_idx').on(t.recipeFoodId),
    check('recipe_ingredients_grams_nonnegative', sql`${t.grams} >= 0`),
  ],
);

export const meals = sqliteTable('meals', {
  id: text().primaryKey(),
  nameMk: text().notNull(),
  nameEn: text().notNull(),
  sortOrder: integer().notNull(),
  isDefault: integer({ mode: 'boolean' }).notNull().default(false),
  isHidden: integer({ mode: 'boolean' }).notNull().default(false),
  ...timestamps,
});

export const logEntries = sqliteTable(
  'logEntries',
  {
    id: text().primaryKey(),
    date: text().notNull(), // 'YYYY-MM-DD', local time
    mealId: text()
      .notNull()
      .references(() => meals.id),
    foodId: text()
      .notNull()
      .references(() => foods.id),
    grams: real().notNull(),
    portionId: text().references(() => portions.id),
    quantity: real(),
    // SNAPSHOT for the logged amount. Editing a food must never change these.
    ...nutrients,
    incompleteNutrients: text({ mode: 'json' }).$type<Nutrient[]>(),
    ...timestamps,
  },
  (t) => [
    index('log_entries_date_idx').on(t.date),
    check('log_entries_grams_positive', sql`${t.grams} > 0`),
  ],
);

// foods_fts (FTS5 virtual table) is created in a custom migration — Drizzle
// can't model virtual tables. It is kept in sync with `foods` by triggers.
